validator:
function validate(input) {
  const [{ Views = [] }] = input;
  const author = new Map();
  for (const [article, writer, viewer, date] of Views) {
    if (article === null || writer === null || viewer === null || date === null) return 'Every column of Views is required.';
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return `view_date ${date} is not YYYY-MM-DD.`;
    if (author.has(article) && author.get(article) !== writer) return `Article ${article} has two authors.`;
    author.set(article, writer);
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const small = size === 'small';
  const articles = small ? 4 : 500, people = small ? 5 : 300, rows = small ? pick(9) : 2000;
  // Authors come from the same pool of people as viewers, so authors sometimes read their own articles.
  const author = [];
  for (let a = 1; a <= articles; a++) author[a] = 1 + pick(small ? people : 200);
  const dates = small ? ['2019-07-21', '2019-08-01', '2019-08-02'] : Array.from({ length: 60 }, (_, i) => new Date(Date.UTC(2019, 6, 1 + i)).toISOString().slice(0, 10));
  const Views = [];
  for (let i = 0; i < rows; i++) {
    if (Views.length && rand() < 0.2) { Views.push([...Views[pick(Views.length)]]); continue; }
    const article = 1 + pick(articles);
    Views.push([article, author[article], 1 + pick(people), dates[pick(dates.length)]]);
  }
  return [{ Views }];
}
